T minCost = std::numeric_limits<T>::max();
*minCostAxis = -1;

T size[3] = {bmax.x - bmin.x, bmax.y - bmin.y, bmax.z - bmin.z};
T surfaceArea = size[0] * size[1] + size[1] * size[2] + size[2] * size[0];

for (int axis = 0; axis < 3; ++axis) {
    T axisSize = size[axis];
    if (axisSize <= 0) continue;

    T currentMinCost = std::numeric_limits<T>::max();
    T bestCut = 0;

    // Precompute prefix sums for primitives and bounds
    // BinBuffer typically stores counts and combined bounds per bin
    int totalPrims = bins->GetTotalPrimitives();
    if (totalPrims <= 1) continue;

    T leftArea = 0;
    int leftCount = 0;
    real3<T> leftBoundsMin = {std::numeric_limits<T>::max(), std::numeric_limits<T>::max(), std::numeric_limits<T>::max()};
    real3<T> leftBoundsMax = {std::numeric_limits<T>::lowest(), std::numeric_limits<T>::lowest(), std::numeric_limits<T>::lowest()};

    for (int i = 0; i < bins->GetBinCount() - 1; ++i) {
        const auto& bin = bins->GetBin(axis, i);
        if (bin.count == 0) continue;

        leftCount += bin.count;
        leftBoundsMin = nanort::Min(leftBoundsMin, bin.boundsMin);
        leftBoundsMax = nanort::Max(leftBoundsMax, bin.boundsMax);

        // Calculate right side bounds and count
        int rightCount = totalPrims - leftCount;
        real3<T> rightBoundsMin = {std::numeric_limits<T>::max(), std::numeric_limits<T>::max(), std::numeric_limits<T>::max()};
        real3<T> rightBoundsMax = {std::numeric_limits<T>::lowest(), std::numeric_limits<T>::lowest(), std::numeric_limits<T>::lowest()};

        for (int j = i + 1; j < bins->GetBinCount(); ++j) {
            const auto& rBin = bins->GetBin(axis, j);
            if (rBin.count == 0) continue;
            rightBoundsMin = nanort::Min(rightBoundsMin, rBin.boundsMin);
            rightBoundsMax = nanort::Max(rightBoundsMax, rBin.boundsMax);
        }

        T dL[3] = {leftBoundsMax.x - leftBoundsMin.x, leftBoundsMax.y - leftBoundsMin.y, leftBoundsMax.z - leftBoundsMin.z};
        T dR[3] = {rightBoundsMax.x - rightBoundsMin.x, rightBoundsMax.y - rightBoundsMin.y, rightBoundsMax.z - rightBoundsMin.z};

        T areaL = dL[0] * dL[1] + dL[1] * dL[2] + dL[2] * dL[0];
        T areaR = dR[0] * dR[1] + dR[1] * dR[2] + dR[2] * dR[0];

        T cost = (leftCount * areaL + rightCount * areaR) / surfaceArea;

        if (cost < currentMinCost) {
            currentMinCost = cost;
            bestCut = bmin[axis] + (T(i + 1) / bins->GetBinCount()) * axisSize;
        }
    }

    if (currentMinCost < minCost) {
        minCost = currentMinCost;
        *minCostAxis = axis;
        cut_pos[axis] = bestCut;
    }
}

return *minCostAxis != -1;

